import {createQQAudio} from './qq-audio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={close:'<path d="m6 6 12 12M18 6 6 18"/>',play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',next:'<path d="m5 5 10 7-10 7ZM19 5v14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',send:'<path d="m3 10 18-7-7 18-4-7-7-4Zm7 4L21 3"/>'};
const icon=k=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[k]+'</svg>';
export function createRadio({cloud,context,modal,records}){
 let data={configured:false,hearts:[],gifts:[]},tracks=[],current=null,mode='discover',queue=[],error='',loading=false,saving=false,requestId=0,playId=0;
 let playingMode='discover',playingTracks=[],listing=false,resumeAt=null;const sessions=new Map();const labels={discover:'随心听',hearts:'我的红心',gifts:'你留的歌'};
 const displayed=()=>mode===playingMode?current:tracks.find(t=>t.id===sessions.get(mode)?.track.id)||tracks[0]||null;
 const unavailable=new Set();let skips=0,skipTimer=null;
 const audio=createQQAudio();
 window.addEventListener('echoo-sleep-play',()=>audio.pause());
 audio.addEventListener('play',()=>window.dispatchEvent(new Event('echoo-music-play')));
 const mini=document.createElement('div');mini.className='fm-mini';mini.hidden=true;document.body.append(mini);
 const launch=document.createElement('button');launch.className='round music-launch';launch.type='button';launch.setAttribute('aria-label','打开音乐播放器');launch.title='听音乐';launch.textContent='♫';document.querySelector('.header-actions')?.prepend(launch);launch.addEventListener('click',()=>open());
 const active=()=>document.querySelector('#panel').open&&context().panel==='radio';
 const btn=(action,label,glyph,cls='')=>'<button type="button" data-fm="'+action+'" aria-label="'+label+'" title="'+label+'" class="fm-icon '+cls+'">'+icon(glyph)+'</button>';
 function message(text){error=text;const el=document.querySelector('[data-fm-status]');if(el)el.textContent=text;mini.title=text;}
 function paint(){
  if(current){const key=current.id+'|'+current.cover;if(mini.dataset.track!==key){mini.dataset.track=key;mini.innerHTML='<button class="fm-mini-cover" data-fm="open" aria-label="展开播放器">'+(current.cover?'<img src="'+esc(current.cover)+'" alt="" referrerpolicy="no-referrer">':'♫')+'</button>'+btn('toggle','播放','play')+btn('next','下一首','next');mini.setAttribute('aria-label','音乐播放控制')}}

  context().visual?.music(!!current&&!audio.paused);
  const shown=displayed(),preview=mode!==playingMode,liked=shown&&data.hearts.includes(shown.id);
  document.querySelectorAll('[data-fm=toggle]').forEach(b=>{const switchList=!mini.contains(b)&&mode!==playingMode;const label=switchList?'播放'+labels[mode]:audio.paused?'播放':'暂停';b.innerHTML=icon(switchList||audio.paused?'play':'pause');b.setAttribute('aria-label',label);b.title=label;b.disabled=loading||(switchList?listing||!tracks.length:!current)});
  document.querySelectorAll('[data-fm=heart]').forEach(b=>{b.classList.toggle('is-liked',!!liked);b.setAttribute('aria-pressed',String(!!liked));b.setAttribute('aria-label',liked?'取消红心':'红心收藏');b.disabled=saving||!shown});
  document.querySelectorAll('[data-fm=next]').forEach(b=>b.disabled=loading||(!mini.contains(b)&&preview?listing||!tracks.length:!playingTracks.length));
  const seek=document.querySelector('[data-fm-seek]');if(seek){seek.max=preview?shown?.duration||0:Number.isFinite(audio.duration)?audio.duration:current?.duration||0;seek.value=preview?sessions.get(mode)?.time||0:audio.currentTime||0;seek.disabled=preview||!Number.isFinite(audio.duration);}
  const time=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');const counter=document.querySelector('[data-fm-time]');if(counter)counter.textContent=time(preview?sessions.get(mode)?.time||0:audio.currentTime||0)+' / '+time(preview?shown?.duration||0:Number.isFinite(audio.duration)?audio.duration:current?.duration||0);
  mini.hidden=!current||active();launch.hidden=!!current||active();document.querySelector('.fm-art')?.classList.toggle('is-playing',!preview&&!!current&&!audio.paused);document.body.classList.toggle("has-music",!!current);mini.classList.toggle('is-playing',!audio.paused);


 }
 function render(){
  const moreOpen=document.querySelector('.fm-more')?.open||false;const t=displayed();
  modal('radio','',labels[mode],`<section class="echoo-fm"><div class="fm-art" role="img" aria-label="唱片封面">${t?.cover?'<img src="'+esc(t.cover)+'" alt="'+esc(t.title)+'的封面" referrerpolicy="no-referrer">':'<span class="fm-art-empty">♫</span>'}<span class="cd-hole"></span></div><h3 class="fm-song">${esc(t?.title||(listing?'正在找歌…':'还没有歌曲'))}</h3><p class="fm-artist">${esc(t?.artist||'')}</p><div class="fm-timeline"><input type="range" min="0" max="0" value="0" aria-label="播放进度" data-fm-seek><small data-fm-time></small></div><div class="fm-controls fm-primary-controls">${btn('heart','红心收藏','heart')+btn('toggle','播放','play','fm-play')+btn('next','下一首','next')+btn('gift','留给对方','send')}</div><p class="fm-status" data-fm-status role="status" aria-live="polite">${esc(error)}</p><details class="fm-more" ${moreOpen?'open':''}><summary>歌单与更多</summary><div class="fm-tabs">${[['discover','随心听'],['hearts','我的红心'],['gifts','你留的歌']].map(([id,label])=>'<button data-fm="channel" data-mode="'+id+'" class="'+(mode===id?'selected':'')+'">'+label+'</button>').join('')}</div><p class="fm-browse-status">${listing?'正在载入…':labels[mode]+' · '+tracks.length+' 首'}${mode!==playingMode?' · 点击播放切换':''}</p>${mode==='gifts'?'<div class="fm-gifts">'+data.gifts.filter(g=>g.track===t?.id).map(g=>'<blockquote>'+esc(g.message||'这首歌，想让你也听见。')+'</blockquote>').join('')+'</div>':''}<div class="fm-credit">${t?'<a href="'+esc(t.url)+'" target="_blank" rel="noopener noreferrer">在 QQ 音乐打开 ↗</a>':''}</div><div class="fm-footer"><button data-fm="reload">刷新曲池</button><button data-fm="records">留歌唱片</button><button data-fm="settings">添加歌曲</button><button data-fm="stop">关闭音乐</button></div></details></section>`);
  const image=document.querySelector('.fm-art img');if(image)image.onerror=()=>{image.remove();message('封面暂未载入')};
  document.querySelector('[data-fm=next]').disabled=loading||!playingTracks.length;document.querySelector('[data-fm=gift]').disabled=saving||!t;
  paint();
 }
 async function load(){const id=++requestId,requestedMode=mode;listing=true;error='';if(active())render();
  try{if(!cloud)throw Error('阿球 FM 需要登录云端版。');const r=await cloud.radioView(requestedMode);if(id!==requestId)return;data=r;tracks=r.tracks;if(requestedMode===playingMode){playingTracks=tracks;queue=queue.filter(t=>tracks.some(x=>x.id===t.id))}error=r.notice||'';if(!r.configured)error=r.canConfigure?'还没有连接音乐来源，请点下方「音乐设置」。':'音乐来源尚未配置，请让第一位住户完成音乐设置。';else if(!tracks.length)error=mode==='hearts'?'点一颗红心，把喜欢的歌留在这里。':mode==='gifts'?'这里等着对方留给你的一首歌。':'暂时没有找到歌曲，请重试。';
  }catch(e){if(id!==requestId)return;error=e.message||'歌曲暂时没有加载成功。'}finally{if(id===requestId){listing=false;if(!current&&tracks.length){current=tracks[Math.floor(Math.random()*tracks.length)];playingMode=requestedMode;playingTracks=tracks;}if(active())render()}}
 }
 function remember(){if(current)sessions.set(playingMode,{track:current,time:audio.currentTime,queue:[...queue]})}
 async function activate(){if(listing||loading||!tracks.length)return;remember();const saved=sessions.get(mode);playingMode=mode;playingTracks=tracks;queue=saved?.queue?.filter(t=>tracks.some(x=>x.id===t.id))||[];const track=saved&&tracks.find(t=>t.id===saved.track.id)||tracks[0];return play(track,saved&&track.id===saved.track.id?saved.time:0)}
 async function play(t,position=0){if(!t||!cloud)return;clearTimeout(skipTimer);const token=++playId;resumeAt=null;audio.pause();audio.removeAttribute('src');audio.load();current=t;loading=true;message('正在连接这首歌…');if(active())render();
  try{const r=await cloud.radioTrack(t.id);if(token!==playId)return;current=r.track;audio.src=r.track.mid;audio.load();resumeAt=position>0?{token,seconds:position}:null;loading=false;if(active())render();try{await audio.play();message('')}catch{message('点一下播放，开始听这首歌。')}}catch(e){if(token===playId){loading=false;message(e.message||'这首歌暂时无法播放，试试下一首。')}}finally{if(token===playId)paint()}
 }
 function shuffled(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
 async function next(){if(loading)return;if(!playingTracks.length)return;if(!queue.length)queue=shuffled(playingTracks.filter(t=>t.id!==current?.id&&!unavailable.has(t.id)));const t=queue.shift();if(!t){message('暂时没有其他可播放歌曲，请重新加载曲池。');return}return play(t)}
 async function toggle(){clearTimeout(skipTimer);skips=0;if(!current)return;if(!audio.paused){audio.pause();return}if(!audio.src)return play(current);try{await audio.play();message('')}catch{message('浏览器未能开始播放，请再点一次，或试试下一首。')}}
 async function mutate(payload){if(saving)return null;saving=true;paint();try{const r=await cloud.radio(payload);if(!r)throw Error(cloud.lastActionError||'暂时没有保存成功');data={...data,...r};return r}catch(e){message(e.message);return null}finally{saving=false;paint()}}
 function settings(){modal('radio-settings','A SONG FOR OUR LITTLE WORLD','添加 QQ 音乐歌曲',`<p class="subtle">打开 QQ 音乐的歌曲网页，复制歌曲详情链接，粘贴到这里。「随心听」会自动载入 QQ 公开榜单，也可以把喜欢的歌曲加入曲池。</p><p class="subtle">支持含 songmid 的链接或 y.qq.com/n/ryqq/songDetail/ 开头的歌曲地址。短分享链接暂不支持。部分歌曲可能需要到 QQ 音乐登录或开通会员。</p><form id="fm-config"><label>歌曲链接<input name="link" autocomplete="off" required maxlength="2000" placeholder="https://y.qq.com/n/ryqq/songDetail/…"></label><button class="pill primary" type="submit">加入曲池</button><p role="status" data-fm-config-status></p></form><button class="pill" data-fm="open">返回播放器</button>`)}
 function gift(){if(!displayed())return;if(!cloud.paired){message('先在「账号与配对」连接对方，再把这首歌留给 TA。');return}const t=displayed();modal('radio-gift','THIS SONG MADE ME THINK OF YOU','把这首歌，留给你',`<p>《${esc(t.title)}》 · ${esc(t.artist)}</p><form id="fm-gift" data-track="${t.id}"><label>想说的话<textarea name="message" maxlength="500" placeholder="听到这首歌的时候，想起了你。"></textarea></label><button class="pill primary" type="submit">留给对方</button><p role="status" data-fm-gift-status></p></form><button class="pill" data-fm="open">返回播放器</button>`)}
 function stop(){++requestId;++playId;clearTimeout(skipTimer);skipTimer=null;audio.pause();audio.removeAttribute('src');current=null;loading=false;listing=false;resumeAt=null;sessions.clear();queue=[];error='';if(active())document.querySelector('#panel').close();paint()}
 async function click(e){const b=e.target.closest('[data-fm]');if(!b||b.disabled)return;switch(b.dataset.fm){case'open':return open();case'stop':return stop();case'toggle':if(!mini.contains(b)&&mode!==playingMode)return activate();return toggle();case'next':skips=0;if(!mini.contains(b)&&mode!==playingMode)return activate();return next();case'channel':if(mode!==b.dataset.mode)tracks=[];mode=b.dataset.mode;return load();case'reload':unavailable.clear();skips=0;if(!loading)return load();return;case'heart':if(displayed()){const selected=displayed(),liked=!data.hearts.includes(selected.id);if(await mutate({action:'heart',id:selected.id,liked})){if(!liked){if(mode==='hearts')tracks=tracks.filter(t=>t.id!==selected.id);if(playingMode==='hearts'){playingTracks=playingTracks.filter(t=>t.id!==selected.id);queue=queue.filter(t=>t.id!==selected.id)}}if(active())render();message(liked?'已收进自己的红心。':'已取消红心。')}}return;case'gift':return gift();case'settings':return settings();case'records':return records();}}
 document.querySelector('#panel-body').addEventListener('click',click);mini.addEventListener('click',click);
 document.querySelector('#panel-body').addEventListener('input',e=>{if(e.target.matches('[data-fm-seek]')&&mode===playingMode&&Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)});
 document.querySelector('#panel-body').addEventListener('submit',async e=>{const f=e.target;if(!['fm-config','fm-gift'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button[type=submit]'),out=f.querySelector('[role=status]');if(b.disabled)return;b.disabled=true;out.textContent='正在保存…';try{const d=Object.fromEntries(new FormData(f));const r=await mutate(f.id==='fm-config'?{action:'add',link:d.link.trim()}:{action:'gift',id:f.dataset.track,message:d.message});if(!r){out.textContent=error;return}if(f.id==='fm-config'){mode='discover';await open();}else{f.reset();out.textContent='已经留给对方，也写进共同手账了。';}}finally{b.disabled=false}});
 audio.addEventListener('play',()=>{if(resumeAt&&resumeAt.token===playId){audio.currentTime=resumeAt.seconds;resumeAt=null}skips=0;message('');paint()});audio.addEventListener('pause',paint);audio.addEventListener('timeupdate',paint);audio.addEventListener('loadedmetadata',paint);audio.addEventListener('ended',next);audio.addEventListener('error',()=>{if(current)unavailable.add(current.id);queue=queue.filter(t=>!unavailable.has(t.id));if(++skips<=8&&playingTracks.some(t=>t.id!==current?.id&&!unavailable.has(t.id))){message('这首歌暂不可播，正在换下一首…');clearTimeout(skipTimer);skipTimer=setTimeout(()=>next(),700)}else message('连续多首暂不可播，已停止尝试。可以重新加载，或在 QQ 音乐打开。');paint()});
 document.addEventListener('click',e=>{if(e.target.closest('[data-do=logout]')){stop()}});
 new MutationObserver(paint).observe(document.querySelector('#panel'),{attributes:true,attributeFilter:['open','data-page']});
 async function open(){render();if(!tracks.length)await load()}
 return {open};
}
